   auto path=world.Navigation().FindPath({5,.1f,0},{5,.1f,-24});check(path.status==NavigationPath::Status::Complete,"cross-region route through ordinary explicit link");
   auto target=world.Physics().GetTransform(world.RuntimeBody(plate));auto before=world.Physics().GetLinearVelocity(world.RuntimeBody(plate));world.Physics().ApplyImpulseAtPoint(world.RuntimeBody(plate),{0,0,-8},target.position);check(world.Physics().GetLinearVelocity(world.RuntimeBody(plate))!=before,"streamed target receives real hit-point impulse");
