 Application app;char program[]="judas";char* arguments[]={program,project.data()};int result=app.Run(2,arguments,&control);check(result==0,"normal standalone application exits");std::ofstream stats(out/"summary.json");stats<<"{\"baseline\":\""<<baseline<<"\",\"checks\":"<<checks<<",\"failures\":"<<failures<<",\"frames\":"<<frames<<",\"integration_ms\":[";for(size_t i=0;i<work.size();++i){if(i)stats<<",";stats<<work[i];}stats<<"]}\n";std::printf("M59 application %d checks %d failures\n",checks,failures);return failures?1:0;
